function fakeFetchUser(id) {
  return new Promise(resolve => {
    setTimeout(() => resolve(`user-${id}`), 100 - id * 10);
  });
}

async function printUsers(ids) {
  ids.forEach(async (id) => {
    const user = await fakeFetchUser(id);
    console.log(user);
  });
  console.log('done looping');
}

printUsers([1, 2, 3]);

async function getTotalOrders(userIds) {
  let total = 0;
  for (const id of userIds) {
    const orders = await db.getOrders(id);
    total += orders.length;
  }
  return total;
}

exercises.solutionCode:
async function getTotalOrders(userIds) {
  const ordersPerUser = await Promise.all(
    userIds.map(id => db.getOrders(id))
  );
  return ordersPerUser.reduce((total, orders) => total + orders.length, 0);
}

sections.body:
When Node.js was created in 2009, JavaScript itself had no built-in concept of a module -- no import, no standard way to split code across files and share values between them. Node solved this pragmatically by inventing its own convention, now called **CommonJS**: every file is its own module; require('./math') synchronously loads and runs another file, and whatever that file attached to module.exports is what you get back.

```javascript
// math.js (CommonJS)
function add(a, b) { return a + b; }
module.exports = { add };

// app.js (CommonJS)
const { add } = require('./math');
console.log(add(2, 3));   // 5
```

JavaScript the language eventually got its own official module system, **ES Modules** (ESM), standardized in ES2015 (import/export), designed for browsers and the language itself rather than being Node-specific. It took Node several more years to support ESM properly (stable support landed around Node 12-13), and by that point CommonJS was already the foundation of an enormous existing ecosystem of packages -- so rather than replacing CommonJS, Node ended up supporting both, permanently:

```javascript
// math.mjs (ES Module)
export function add(a, b) { return a + b; }

// app.mjs (ES Module)
import { add } from './math.mjs';
console.log(add(2, 3));   // 5
```

The syntax difference is the visible part, but it's genuinely the smaller part of the story -- the two systems differ in more fundamental ways, covered next, that occasionally surface as real errors rather than just stylistic choices.

Node decides which module system a .js file uses based on the nearest package.json's "type" field: "type": "commonjs" (the default if the field is omitted entirely) makes .js files CommonJS; "type": "module" makes them ESM. You can also sidestep that entirely and force a specific file's system regardless of the package-level setting, using the explicit .cjs or .mjs extensions.

Switching a project to "type": "module" changes more than just import syntax -- several CommonJS-only globals simply don't exist in ESM files: require, module, exports, __dirname, and __filename are all undefined there, because they were never part of the language's own module spec, only Node's CommonJS implementation of it. The idiomatic ESM replacement for __dirname/__filename uses the standard import.meta.url together with the url and path core modules:

```javascript
import { fileURLToPath } from 'url';
import path from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
```

Mixing the two systems in the same project is supported but asymmetric, and the asymmetry is exactly where real errors come from. An ESM file **can** import a CommonJS module reasonably smoothly -- Node treats the CJS module's module.exports as the default export. But a CommonJS file **cannot** require() an ESM module at all -- require() is synchronous, and ESM loading is fundamentally asynchronous, so there is no way to make that work, and attempting it throws Error [ERR_REQUIRE_ESM]: require() of ES Module ... not supported. The only way to load an ESM module from CommonJS code is the dynamic import('./thing.mjs') function, which returns a Promise -- you cannot get a synchronous result back the way require normally gives you one.

examples.code:
// --- CommonJS: mathUtils.js ---
function square(n) {
  return n * n;
}
module.exports = { square };

// --- CommonJS: app.js ---
const { square } = require('./mathUtils');
console.log(square(4));   // 16


// --- ES Module: mathUtils.mjs ---
export function square(n) {
  return n * n;
}

// --- ES Module: app.mjs ---
import { square } from './mathUtils.mjs';
console.log(square(4));   // 16

// a.js
console.log('a.js starts');
module.exports.value = 1;
const b = require('./b');
console.log('a.js sees b.value =', b.value);
module.exports.value = 2;

// b.js
console.log('b.js starts');
module.exports.value = 10;
const a = require('./a');
console.log('b.js sees a.value =', a.value);   // 1, not 2 -- a.js isn't finished yet
module.exports.value = 20;

// main.js
const a = require('./a');
console.log('main.js sees a.value =', a.value);

// utils.mjs
import { fileURLToPath } from 'url';
import path from 'path';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const configPath = path.join(__dirname, 'config.json');
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
console.log(config);

